select
  cast('__dbt__cte__poden__contract_00000000000000000000000000000002' as string) as contract_relation,
  cast(2840 as int64) as location_code,
  cast('en' as string) as language_code,
  cast('{"request_kind":"domain_rankings","location_code":2840,"language_code":"en","order_by":[],"filters":"[]"}' as string) as query_settings,
  cast(1900 as int64) as rows_held,
  cast(100 as int64) as overlap_rows,
  cast(2500 as int64) as last_observed_total,
  cast('second' as string) as last_run_id,
  cast('2026-10-30' as date) as last_run_date
